ALTER POLICY "Specialists can view their own orders" ON public.orders TO authenticated USING (NOT public.is_admin_or_staff_user() AND status IN ('pending','approved','completed') AND EXISTS (SELECT 1 FROM public.specialists s WHERE s.user_id=auth.uid() AND lower(trim(s.email))=lower(trim(orders.customer_email)))); REVOKE ALL ON FUNCTION public.owns_payment_email(text) FROM authenticated;